import {icon} from './app.js?v=20261106d';
export function credits(){return `<div class="page-heading"><div><h1>Explore kindly. Check carefully.</h1><p>Good scientists look after people as well as plants.</p></div></div><section class="safety-list"><div>${icon('shield')}<h2>Keep private things private.</h2><p>Never share your password, full name, address or a friend's photo with an AI tool. Ask an adult before using a new service.</p></div><div>${icon('search')}<h2>Check before you believe.</h2><p>Compare a claim with a science textbook or a named science organisation. An attractive picture or confident answer can still be inaccurate.</p></div><div>${icon('book')}<h2>Give credit.</h2><p>Say where ideas and pictures came from. Tell your teacher if AI helped. Do not pretend someone else's work is your own.</p></div></section><section class="activity-panel teacher-section"><h2>Where our science comes from</h2><ul class="source-list"><li><strong><em>Science Year 4</em>, Unit 4.</strong> User-supplied KSSR textbook, printed pages 76–81. Primary science content; ideas paraphrased and diagrams newly made. The full textbook is not redistributed.</li><li><strong>KSSR Science Year 4 DSKP, Semakan 2017.</strong> Supplied curriculum document, printed page 54: 4.2 Photosynthesis, standards 4.2.1–4.2.4. The document is Year 4; the earlier Year 2 note was incorrect.</li><li><strong>NASA Science. (n.d.). <em>What is the carbon cycle?</em></strong> Independent science cross-check. <a href="https://science.nasa.gov/kids/earth/what-is-the-carbon-cycle/" target="_blank" rel="noopener noreferrer">Read with an adult ↗</a></li><li><strong>Royal Horticultural Society. Plant science references.</strong> Water moves through roots and internal vessels; leaf pores exchange gases, and chlorophyll absorbs light. <a href="https://www.rhs.org.uk/advice/understanding-plants/how-plants-absorb-water" target="_blank" rel="noopener noreferrer">Water transport</a> · <a href="https://www.rhs.org.uk/advice/understanding-plants/how-plants-breathe" target="_blank" rel="noopener noreferrer">Gas exchange</a> · <a href="https://www.rhs.org.uk/advice/understanding-plants/how-plants-use-light-to-grow" target="_blank" rel="noopener noreferrer">Chlorophyll and light</a></li><li><strong>Kementerian Pendidikan Malaysia. (2026). <em>Panduan Literasi Kecerdasan Buatan (AI).</em></strong> <a href="https://www.moe.gov.my/surat-pekeliling-ikhtisas-kpm-ai" target="_blank" rel="noopener noreferrer">Official guide and circular ↗</a></li><li><strong>NASA. (n.d.). <em>STEMonstrations: Photosynthesis.</em></strong> Optional teacher-led extension video; aimed at older pupils, outside the core lesson. <a href="https://www.nasa.gov/stem-content/stemonstrations-photosynthesis/" target="_blank" rel="noopener noreferrer">Visit NASA's video page ↗</a></li></ul></section><section class="activity-panel teacher-section"><h2>How this learning space was made</h2><p>Code, activity drafts and original garden and character artwork were created with assistance from OpenAI Codex and image generation. The storybook characters and garden scenes use original AI-assisted illustrations. The plant diagrams use interactive SVG geometry. Science was checked against the supplied textbook and the linked NASA and RHS sources. The teacher checks the science, media and learning activities before classroom use.</p><p>AI assistance was used by the developer to prepare learning materials. There is no live chatbot or pupil AI activity. The garden character is fictional; its face is decorative.</p><p>Typefaces: <strong>Nunito</strong>, <strong>Lilita One</strong> and <strong>Caveat</strong>, under the SIL Open Font License (<a href="assets/OFL-Nunito.txt">Nunito</a>, <a href="assets/OFL-LilitaOne.txt">Lilita One</a>, <a href="assets/OFL-Caveat.txt">Caveat</a>). Icons and instructional diagrams are original SVG geometry. Sound cues are generated by the browser.</p><p><strong>Greenhaven 3D assets:</strong> nature models are from <a href="https://quaternius.com/packs/stylizednaturemegakit.html" target="_blank" rel="noopener noreferrer">Quaternius’s Stylized Nature MegaKit Standard</a> (CC0; <a href="assets/grove/nature-license.txt">included license</a>). Nico uses the Timmy character supplied through Adobe Mixamo, as identified by the developer. Mixamo characters and animations are royalty-free for use within projects; they are not CC0. <a href="https://www.mixamo.com/" target="_blank" rel="noopener noreferrer">Mixamo</a> · <a href="https://helpx.adobe.com/creative-cloud/faq/mixamo-faq.html" target="_blank" rel="noopener noreferrer">Adobe usage guidance</a>. The procedural Sprout model, creek gate and scene code were created with Codex assistance. Downloaded models are not claimed as the student’s original artwork. Three.js is used under its <a href="vendor/three/LICENSE.txt">MIT license</a>. This scene stores an optional explorer nickname locally and sends no pupil answers to a server.</p><p>External links open another website, which has its own privacy terms. No external video is loaded automatically.</p></section><a class="btn" href="#map">${icon('map')} Back to my adventure</a>`}
